argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$head=(& git.exe -C $repo rev-parse HEAD).Trim();
$branches=@(& git.exe -C $repo branch -r --contains $head);
$paths=@(
'app/scripts/operator-lifecycle-r40.ps1',
'app/scripts/pause-all-r40.cmd',
'app/scripts/pause-browser-r40.cmd',
'app/scripts/resume-attach-r40.cmd',
'app/scripts/resume-managed-r40.cmd'
);
$rows=@();
foreach($p in $paths){
  $headBlob=(& git.exe -C $repo rev-parse ('HEAD:'+$p) 2>$null);
  $workBlob=(& git.exe -C $repo hash-object --no-filters -- $p 2>$null);
  $rows += [pscustomobject]@{path=$p;headBlob=($headBlob|Out-String).Trim();workBlob=($workBlob|Out-String).Trim();rawIdentical=((($headBlob|Out-String).Trim()) -eq (($workBlob|Out-String).Trim()))}
}
[pscustomobject]@{head=$head;remoteBranches=$branches;files=$rows}|ConvertTo-Json -Depth 6 -Compress
